defaultpen(fontsize(10pt));
pair A=(0,0),B=(12,0),C=(12,12),D=(0,12),P=(-4,0),Q=(0,3);
draw(A--B--C--D--cycle,linewidth(0.9));
draw(P--A,linewidth(0.9));draw(P--C,red+linewidth(0.9));
